-- Part 6 (diversification pass): online MCQ bank (comp_mcq_questions) for welding_supervisor
-- ("سرپرست جوشکاری"). ZERO rows before this seed (verified via the MCQ count-per-role audit
-- query). 30 questions, APPROVED and active, spanning TECHNICAL/GENERAL/HSE/SCENARIO/
-- JUDGMENT/PROBLEM_SOLVING/CASE_STUDY, difficulty 1-3, varied stem formats. Domain grounding:
-- AWS D1.1 / ASME Section IX (WPS/PQR/welder qualification), API 1104 (pipeline welding),
-- preheat/interpass temperature and heat-input calculation, NDT sequencing, welding-fume and
-- arc/confined-space HSE.
-- Same rotation technique as supabase/seed/mcq_questions_seed.sql. Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'welding_supervisor', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
